794-    int i, ok;
795-    if (c->l_qname - c->l_extranul > 255) {
796-        hts_log_error("QNAME \"%s\" is longer than 254 characters", bam_get_qname(b));
797-        errno = EOVERFLOW;
798-        return -1;
799-    }
800-    if (c->n_cigar > 0xffff) block_len += 16; // "16" for "CGBI", 4-byte tag length and 8-byte fake CIGAR
801-    if (c->pos > INT_MAX ||
802-        c->mpos > INT_MAX ||
803-        c->isize < INT_MIN || c->isize > INT_MAX) {
804-        hts_log_error("Positional data is too large for BAM format");
805-        return -1;
806-    }
807-    x[0] = c->tid;
808-    x[1] = c->pos;
809-    x[2] = (uint32_t)c->bin<<16 | c->qual<<8 | (c->l_qname - c->l_extranul);
810-    if (c->n_cigar > 0xffff) x[3] = (uint32_t)c->flag << 16 | 2;
811-    else x[3] = (uint32_t)c->flag << 16 | (c->n_cigar & 0xffff);
812-    x[4] = c->l_qseq;
813-    x[5] = c->mtid;
814-    x[6] = c->mpos;
815-    x[7] = c->isize;
816-    ok = (bgzf_flush_try(fp, 4 + block_len) >= 0);
817-    if (fp->is_be) {
818-        for (i = 0; i < 8; ++i) ed_swap_4p(x + i);
819-        y = block_len;
820-        if (ok) ok = (bgzf_write(fp, ed_swap_4p(&y), 4) >= 0);
821-        swap_data(c, b->l_data, b->data, 1);
822-    } else {
823-        if (ok) ok = (bgzf_write(fp, &block_len, 4) >= 0);
824-    }
825-    if (ok) ok = (bgzf_write(fp, x, 32) >= 0);
826-    if (ok) ok = (bgzf_write(fp, b->data, c->l_qname - c->l_extranul) >= 0);
827-    if (c->n_cigar <= 0xffff) { // no long CIGAR; write normally
828-        if (ok) ok = (bgzf_write(fp, b->data + c->l_qname, b->l_data - c->l_qname) >= 0);
829-    } else { // with long CIGAR, insert a fake CIGAR record and move the real CIGAR to the CG:B,I tag
830-        uint8_t buf[8];
831-        uint32_t cigar_st, cigar_en, cigar[2];
832-        hts_pos_t cigreflen = bam_cigar2rlen(c->n_cigar, bam_get_cigar(b));
833-        if (cigreflen >= (1<<28)) {
834-            // Length of reference covered is greater than the biggest
835-            // CIGAR operation currently allowed.
836-            hts_log_error("Record %s with %d CIGAR ops and ref length %"PRIhts_pos
837-                          " cannot be written in BAM.  Try writing SAM or CRAM instead.\n",
838-                          bam_get_qname(b), c->n_cigar, cigreflen);
839-            return -1;
840-        }
841-        cigar_st = (uint8_t*)bam_get_cigar(b) - b->data;
842-        cigar_en = cigar_st + c->n_cigar * 4;
843-        cigar[0] = (uint32_t)c->l_qseq << 4 | BAM_CSOFT_CLIP;
844-        cigar[1] = (uint32_t)cigreflen << 4 | BAM_CREF_SKIP;
845-        u32_to_le(cigar[0], buf);
846-        u32_to_le(cigar[1], buf + 4);
847-        if (ok) ok = (bgzf_write(fp, buf, 8) >= 0); // write cigar: <read_length>S<ref_length>N
848-        if (ok) ok = (bgzf_write(fp, &b->data[cigar_en], b->l_data - cigar_en) >= 0); // write data after CIGAR
849-        if (ok) ok = (bgzf_write(fp, "CGBI", 4) >= 0); // write CG:B,I
850-        u32_to_le(c->n_cigar, buf);
851-        if (ok) ok = (bgzf_write(fp, buf, 4) >= 0); // write the true CIGAR length
852-        if (ok) ok = (bgzf_write(fp, &b->data[cigar_st], c->n_cigar * 4) >= 0); // write the real CIGAR
853-    }
854-    if (fp->is_be) swap_data(c, b->l_data, b->data, 0);
855-    return ok? 4 + block_len : -1;
856-}
